-- Bauplattform: Bauteil-Baukasten (Vorlagen mit Schichten) und Standardelemente – erzeugt mit positionsdb/bauteile_gen.py, nicht von Hand ändern
-- 489 Vorlagen, 6583 Standardelemente, Preisstand 2026-11; Preise = Σ Faktor × EP der Positionen (Katalog gk3).
CREATE TABLE IF NOT EXISTS pdb_vorlage(
  id TEXT PRIMARY KEY,                        -- z. B. '331.01'
  kg TEXT NOT NULL DEFAULT '',
  name TEXT NOT NULL DEFAULT '',
  einheit TEXT NOT NULL DEFAULT '',
  lang TEXT NOT NULL DEFAULT '',
  bezug TEXT NOT NULL DEFAULT '',             -- wie die Menge ermittelt wird
  daten TEXT NOT NULL DEFAULT '{}',           -- {"fest": [[code, faktor]], "schichten": [{name, optionen: [{k, t, teile, std}]}]}
  tags TEXT NOT NULL DEFAULT '',
  sort INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS pdb_vorlage_kg ON pdb_vorlage(kg);
-- Bestandteile der Standardelemente (Katalog gk3e): Menge der Position = Faktor × Menge des Elements
CREATE TABLE IF NOT EXISTS pdb_element_teil(
  element_code TEXT NOT NULL,
  nr INTEGER NOT NULL DEFAULT 0,
  position_code TEXT NOT NULL,                -- Code im Katalog gk3
  faktor REAL NOT NULL DEFAULT 1,
  PRIMARY KEY (element_code, nr));
CREATE INDEX IF NOT EXISTS pdb_element_teil_pos ON pdb_element_teil(position_code);
-- Kompakte Vorbemerkungen je Leistungsbereich (key = LB-Nummer) und allgemeine Muster (key = 'bb', 'bvb' …)
CREATE TABLE IF NOT EXISTS pdb_vorbemerkung(
  key TEXT PRIMARY KEY,
  titel TEXT NOT NULL DEFAULT '',
  text TEXT NOT NULL DEFAULT '',
  sort INTEGER NOT NULL DEFAULT 0);
INSERT INTO pdb_katalog(key, name, art, lizenz, preisstand, index_basis, sort) VALUES ('gk3e', 'Bauteile & Elemente Bauplattform', 'katalog', 'Eigene Aufbauten aus der Positionsdatenbank der Bauplattform', '2026-11', 141.7, 3) ON CONFLICT(key) DO UPDATE SET name = excluded.name, preisstand = excluded.preisstand, index_basis = excluded.index_basis;
DELETE FROM pdb_element_teil; DELETE FROM pdb_vorlage; DELETE FROM pdb_position WHERE katalog = 'gk3e';
INSERT INTO pdb_vorlage(id, kg, name, einheit, lang, bezug, daten, tags, sort) VALUES
  ('311.01', '311', 'Baugrubenaushub mit Bodenabfuhr', 'm³', 'Baugrube profilgerecht ausheben, Boden seitlich zwischenlagern, laden und zur Verwertung bzw. Entsorgung abfahren (einschließlich Annahmegebühr der gewählten Zuordnungsklasse). Optional Planum der Sohle anteilig.', 'Aushubvolumen im Abtrag (fest), einschließlich Böschungen und Arbeitsraum', '{"fest": [], "schichten": [{"name": "Aushub", "optionen": [{"k": "B1 ≤1,25 m", "t": "Homogenbereich B1, leicht lösbar, Tiefe bis 1,25 m", "teile": [["002.02.001.01001", 1.0]]}, {"k": "B1 ≤3,5 m", "t": "Homogenbereich B1, leicht lösbar, Tiefe bis 3,5 m", "teile": [["002.02.001.02001", 1.0]], "std": true}, {"k": "B2 ≤3,5 m", "t": "Homogenbereich B2, mittelschwer lösbar, Tiefe bis 3,5 m", "teile": [["002.02.001.03001", 1.0]], "std": true}, {"k": "B2 + 20 % Fels", "t": "Homogenbereich B2 mit ca. 20 % schwer lösbarem Boden/Fels", "teile": [["002.02.001.03001", 1.0], ["002.02.003.01001", 0.2]]}]}, {"name": "Bodenverbleib", "optionen": [{"k": "Z0 abfahren", "t": "Boden laden und abfahren, Z0/BM-0, bis 10 km", "teile": [["002.02.007.01001", 1.8]], "std": true}, {"k": "Z1.1 abfahren", "t": "Boden laden und abfahren, Z1.1/BM-F1, bis 10 km", "teile": [["002.02.007.02001", 1.8]], "std": true}, {"k": "Z1.2 abfahren", "t": "Boden laden und abfahren, Z1.2/BM-F2, bis 10 km", "teile": [["002.02.007.03001", 1.8]]}, {"k": "Z2 abfahren", "t": "Boden laden und abfahren, Z2/BM-F3, bis 10 km", "teile": [["002.02.007.04001", 1.8]], "std": true}, {"k": "50 % Wiedereinbau", "t": "50 % zwischenlagern zum Wiedereinbau, 50 % Z0 abfahren", "teile": [["002.04.007.01001", 0.5], ["002.02.007.01001", 0.9]]}]}, {"name": "Sohle", "optionen": [{"k": "", "t": "", "teile": [], "std": true}, {"k": "mit Planum", "t": "Planum der Baugrubensohle ±3 cm anteilig (Tiefe ca. 3 m)", "teile": [["002.03.001.01001", 0.33]], "std": true}]}]}', 'neubau', 0),
  ('311.02', '311', 'Baugrube Keller je m² Sohle', 'm²', 'Baugrube für ein unterkellertes Gebäude komplett: Oberboden abtragen, Aushub rd. 2,8 m tief mit Böschungen, Boden abfahren, Planum der Sohle und Arbeitsraumverfüllung nach Wahl.', 'Fläche der Baugrubensohle (Gebäudegrundfläche zzgl. Arbeitsraum)', '{"fest": [], "schichten": [{"name": "Oberboden", "optionen": [{"k": "OB 20 lagern", "t": "Oberboden 20 cm abtragen und seitlich lagern", "teile": [["002.01.003.01001", 1.2]], "std": true}, {"k": "OB 30 abfahren", "t": "Oberboden 30 cm abtragen und abfahren", "teile": [["002.01.004.02001", 1.2]], "std": true}, {"k": "ohne Oberboden", "t": "kein Oberboden vorhanden (befestigte Fläche gesondert)", "teile": []}]}, {"name": "Aushub", "optionen": [{"k": "2,8 m B1 Z0", "t": "Aushub B1 bis 2,8 m, direkt laden und abfahren, Z0", "teile": [["002.02.002.01001", 3.2]], "std": true}, {"k": "2,8 m B2 Z0", "t": "Aushub B2 bis 2,8 m, direkt laden und abfahren, Z0", "teile": [["002.02.002.02001", 3.2]], "std": true}, {"k": "2,8 m B1 Z1.1", "t": "Aushub B1 bis 2,8 m, lagern, abfahren Z1.1", "teile": [["002.02.001.02001", 3.2], ["002.02.007.02001", 5.76]], "std": true}, {"k": "3,5 m B1 Z0", "t": "Aushub B1 bis 3,5 m, direkt laden und abfahren, Z0", "teile": [["002.02.002.01001", 4.0]]}, {"k": "1,5 m B1 Z0", "t": "Teilunterkellerung/Souterrain, Aushub B1 bis 1,5 m, Z0", "teile": [["002.02.002.01001", 1.7]]}]}, {"name": "Sohle/Arbeitsraum", "optionen": [{"k": "Planum, AR Kies", "t": "Planum ±3 cm, Arbeitsraum mit Kiessand 0/32 verfüllen", "teile": [["002.03.001.01001", 1.0], ["002.03.003.01001", 0.8]], "std": true}, {"k": "Planum, AR RC", "t": "Planum ±3 cm, Arbeitsraum mit RC 0/45 verfüllen", "teile": [["002.03.001.01001", 1.0], ["002.03.003.02001", 0.8]], "std": true}, {"k": "nur Planum", "t": "Planum ±3 cm, Arbeitsraumverfüllung gesondert", "teile": [["002.03.001.01001", 1.0]]}]}]}', 'neubau', 1),
  ('311.03', '311', 'Fundamentaushub', 'm³', 'Gräben bzw. Gruben für Streifen- und Einzelfundamente ausheben, Boden lagern oder abfahren, Sohle verdichten.', 'Aushubvolumen der Fundamentgräben im Abtrag (fest)', '{"fest": [], "schichten": [{"name": "Aushub", "optionen": [{"k": "Graben B ≤0,6 m", "t": "Fundamentgräben B bis 0,6 m, Tiefe bis 1,0 m", "teile": [["002.02.004.01001", 1.0]], "std": true}, {"k": "Graben B ≤1,0 m", "t": "Fundamentgräben B bis 1,0 m, Tiefe bis 1,5 m", "teile": [["002.02.004.02001", 1.0]], "std": true}, {"k": "Einzelgruben", "t": "Einzelfundamentgruben bis 1,0 m³, Zulage Kleinaushub", "teile": [["002.02.004.02001", 1.0], ["002.04.009.02001", 1.0]], "std": true}, {"k": "Handaushub", "t": "Handaushub B1 (beengte Verhältnisse, Bestand)", "teile": [["002.02.006.01001", 1.0]]}]}, {"name": "Bodenverbleib", "optionen": [{"k": "Z0 abfahren", "t": "Boden laden und abfahren, Z0/BM-0", "teile": [["002.02.007.01001", 1.8]], "std": true}, {"k": "Z1.1 abfahren", "t": "Boden laden und abfahren, Z1.1/BM-F1", "teile": [["002.02.007.02001", 1.8]], "std": true}, {"k": "zwischenlagern", "t": "Boden auf der Baustelle zwischenlagern zum Wiedereinbau", "teile": [["002.04.007.01001", 1.0]], "std": true}]}, {"name": "Sohle", "optionen": [{"k": "", "t": "", "teile": [], "std": true}, {"k": "Sohle verdichtet", "t": "Grabensohle planieren und verdichten (1,25 m² je m³)", "teile": [["002.03.001.01001", 1.25]], "std": true}]}]}', 'neubau', 2),
  ('311.04', '311', 'Arbeitsraumverfüllung', 'm³', 'Arbeitsräume an erdberührten Bauteilen lagenweise verfüllen und verdichten (DPr ≥ 97 %), Abdichtung und Dämmung schützen.', 'Verfülltes Volumen im verdichteten Zustand', '{"fest": [], "schichten": [{"name": "Material", "optionen": [{"k": "Boden seitlich", "t": "seitlich gelagerter, geeigneter Boden", "teile": [["002.03.002.01001", 1.0]], "std": true}, {"k": "Kiessand 0/32", "t": "geliefertes Kiessand 0/32", "teile": [["002.03.003.01001", 1.0]], "std": true}, {"k": "RC 0/45", "t": "geliefertes Recyclingmaterial RC-1 0/45", "teile": [["002.03.003.02001", 1.0]], "std": true}, {"k": "Sand/Kies Graben", "t": "Sand/Kies in schmalen Arbeitsräumen und Gräben", "teile": [["002.04.004.01001", 1.0]]}]}, {"name": "Förderung", "optionen": [{"k": "", "t": "", "teile": [], "std": true}, {"k": "umlagern ≤50 m", "t": "Boden innerhalb der Baustelle fördern, bis 50 m", "teile": [["002.04.008.01001", 1.0]], "std": true}, {"k": "umlagern ≤200 m", "t": "Boden innerhalb der Baustelle fördern, bis 200 m", "teile": [["002.04.008.02001", 1.0]]}]}, {"name": "Prüfung", "optionen": [{"k": "", "t": "ohne Verdichtungsprüfung", "teile": []}, {"k": "LFG-Prüfung", "t": "dynamische Lastplattendruckversuche, 1 je 50 m³", "teile": [["002.04.011.01001", 0.02]], "std": true}, {"k": "Plattendruck", "t": "statischer Plattendruckversuch, 1 je 200 m³", "teile": [["002.03.007.01001", 0.005]], "std": true}]}]}', 'neubau,altbau', 3),
  ('311.05', '311', 'Oberbodenarbeiten', 'm²', 'Oberboden im Baufeld abtragen, seitlich in Mieten lagern oder abfahren; optional teilweise wieder andecken und Bodenprobe zur Deklaration.', 'Abtragsfläche des Oberbodens', '{"fest": [], "schichten": [{"name": "Abtrag", "optionen": [{"k": "OB 20 lagern", "t": "Oberboden 20 cm abtragen, seitlich lagern", "teile": [["002.01.003.01001", 1.0]], "std": true}, {"k": "OB 30 lagern", "t": "Oberboden 30 cm abtragen, seitlich lagern", "teile": [["002.01.003.02001", 1.0]], "std": true}, {"k": "OB 20 abfahren", "t": "Oberboden 20 cm abtragen und abfahren", "teile": [["002.01.004.01001", 1.0]], "std": true}, {"k": "OB 30 abfahren", "t": "Oberboden 30 cm abtragen und abfahren", "teile": [["002.01.004.02001", 1.0]], "std": true}]}, {"name": "Wiederandecken", "optionen": [{"k": "", "t": "", "teile": [], "std": true}, {"k": "50 % andecken", "t": "50 % der Fläche nach Bauende aus Miete wieder andecken, 20 cm", "teile": [["002.01.005.01001", 0.5]], "std": true}, {"k": "100 % andecken", "t": "gesamte Fläche aus Miete wieder andecken, 30 cm", "teile": [["002.01.005.02001", 1.0]]}]}, {"name": "Deklaration", "optionen": [{"k": "", "t": "", "teile": []}, {"k": "mit Bodenprobe", "t": "Bodenprobe und Deklarationsanalyse, 1 je 500 m²", "teile": [["002.02.008.01001", 0.002]], "std": true}, {"k": "Probe + Vermessung", "t": "Bodenprobe 1 je 500 m², Absteckung/Schnurgerüst anteilig 1 je 400 m²", "teile": [["002.02.008.01001", 0.002], ["002.04.012.01001", 0.0025]], "std": true}]}]}', 'neubau', 4),
  ('311.06', '311', 'Baugrube ohne Keller je m²', 'm²', 'Flache Baugrube für ein nicht unterkellertes Gebäude (Bodenplatte auf Gelände): Oberboden abtragen, Aushub bis Gründungsebene, Boden abfahren, Planum herstellen.', 'Gebäudegrundfläche zzgl. 0,5 m Arbeitsraum umlaufend', '{"fest": [], "schichten": [{"name": "Oberboden", "optionen": [{"k": "OB 20 lagern", "t": "Oberboden 20 cm abtragen und seitlich lagern", "teile": [["002.01.003.01001", 1.0]], "std": true}, {"k": "OB 30 abfahren", "t": "Oberboden 30 cm abtragen und abfahren", "teile": [["002.01.004.02001", 1.0]], "std": true}, {"k": "ohne Oberboden", "t": "kein Oberboden", "teile": []}]}, {"name": "Aushub", "optionen": [{"k": "0,5 m B1", "t": "Aushub 0,5 m, B1, direkt abfahren Z0", "teile": [["002.02.002.01001", 0.55]], "std": true}, {"k": "0,8 m B1", "t": "Aushub 0,8 m, B1, direkt abfahren Z0", "teile": [["002.02.002.01001", 0.9]], "std": true}, {"k": "0,8 m B2", "t": "Aushub 0,8 m, B2, direkt abfahren Z0", "teile": [["002.02.002.02001", 0.9]], "std": true}, {"k": "1,2 m B1", "t": "Aushub 1,2 m (Bodenaustausch vorgesehen), B1, Z0", "teile": [["002.02.002.01001", 1.3]]}]}, {"name": "Planum", "optionen": [{"k": "Planum ±3 cm", "t": "Planum ±3 cm, DPr 97 %", "teile": [["002.03.001.01001", 1.0]], "std": true}, {"k": "Planum ±2 cm, PDV", "t": "Planum ±2 cm, Plattendruckversuch 1 je 300 m²", "teile": [["002.03.001.02001", 1.0], ["002.03.007.01001", 0.0033]], "std": true}]}]}', 'neubau', 5),
  ('311.07', '311', 'Aushub im Bestand, beengt', 'm³', 'Aushub bei beengten Verhältnissen im Bestand (Kellerabsenkung, Anbau, Hofbereich) von Hand bzw. mit Minibagger und Dumper, Boden über Container oder Big Bags entsorgen.', 'Aushubvolumen im Abtrag (fest)', '{"fest": [], "schichten": [{"name": "Lösen", "optionen": [{"k": "Handaushub", "t": "Handaushub B1", "teile": [["002.02.006.01001", 1.0]], "std": true}, {"k": "Minibagger", "t": "Minibagger bis 3 t mit Fahrer und Kettendumper, ca. 0,35 h/m³", "teile": [["091.36.001.01001", 0.35], ["091.36.004.01001", 0.35]], "std": true}, {"k": "Mobilbagger", "t": "Mobilbagger 14–18 t mit Fahrer, ca. 0,12 h/m³", "teile": [["091.36.002.01001", 0.12]]}]}, {"name": "Entsorgung", "optionen": [{"k": "Container Z0", "t": "Absetzcontainer 10 m³ (1,3 m³ lose je m³), Boden BM-0 entsorgen", "teile": [["087.05.001.04001", 0.13], ["087.03.001.01001", 1.8]], "std": true}, {"k": "Container Z1.1", "t": "Absetzcontainer 10 m³, Boden BM-F0*/Z1.1 entsorgen", "teile": [["087.05.001.04001", 0.13], ["087.03.001.03001", 1.8]], "std": true}, {"k": "Big Bag Z0", "t": "Big Bags 1 m³ mit Kranabholung, Boden BM-0 entsorgen", "teile": [["087.05.001.09001", 1.3], ["087.03.001.01001", 1.8]], "std": true}]}, {"name": "Leitungssuche", "optionen": [{"k": "", "t": "", "teile": [], "std": true}, {"k": "Suchschachtung", "t": "Suchschachtung von Hand nach Leitungen, 1 je 10 m³", "teile": [["002.04.001.01001", 0.1]], "std": true}]}]}', 'altbau', 6),
  ('312.01', '312', 'Trägerbohlwand (Berliner Verbau)', 'm²', 'Baugrubenverbau als Trägerbohlwand: Stahlträger einbringen, Ausfachung abschnittsweise mit dem Aushub, nach Wahl rückgebaut oder verbleibend, mit Rückverankerung oder Aussteifung und anteiliger Baustelleneinrichtung des Spezialtiefbaus.', 'Ansichtsfläche der Verbauwand (Länge × Verbautiefe)', '{"fest": [], "schichten": [{"name": "Verbau", "optionen": [{"k": "Holz ≤4 m, rück", "t": "Holzausfachung, Verbautiefe bis 4 m, Träger gezogen", "teile": [["006.01.002.01001", 1.0]], "std": true}, {"k": "Holz ≤6 m, rück", "t": "Holzausfachung, Verbautiefe bis 6 m, Träger gezogen", "teile": [["006.01.002.02001", 1.0]], "std": true}, {"k": "Holz verbleibt", "t": "Holzbohlen, bis 4 m, Verbau verbleibt", "teile": [["006.03.001.01001", 1.0]]}, {"k": "StB-FT-Platten", "t": "Ausfachung Stahlbeton-Fertigteilplatten, verbleibt", "teile": [["006.03.001.02001", 1.0]]}, {"k": "Spritzbeton", "t": "Ausfachung Spritzbeton 15 cm bewehrt", "teile": [["006.03.001.03001", 1.0]], "std": true}]}, {"name": "Rückhaltung", "optionen": [{"k": "", "t": "frei auskragend", "teile": [], "std": true}, {"k": "verankert", "t": "Verpressanker Kurzzeit 12 m, 1 je 12,5 m²", "teile": [["006.03.004.01001", 0.08]], "std": true}, {"k": "ausgesteift", "t": "Gurtung und Aussteifung Stahl, ca. 20 kg/m²", "teile": [["006.03.005.01001", 0.02]]}]}, {"name": "Baustelleneinrichtung", "optionen": [{"k": "BE /300 m²", "t": "BE Spezialtiefbau anteilig bei 300 m² Verbaufläche", "teile": [["006.01.001.01001", 0.0033]], "std": true}, {"k": "BE /100 m²", "t": "BE Spezialtiefbau anteilig bei 100 m² Verbaufläche", "teile": [["006.01.001.01001", 0.01]], "std": true}]}]}', 'neubau', 7),
  ('312.02', '312', 'Spundwand', 'm²', 'Baugrubenumschließung aus Stahlspundbohlen, eingerammt bzw. eingerüttelt, rückgebaut oder verbleibend, mit Gurtung/Ankern nach Statik und anteiliger Baustelleneinrichtung.', 'Ansichtsfläche der Spundwand (Länge × Einbindetiefe)', '{"fest": [], "schichten": [{"name": "Spundwand", "optionen": [{"k": "Profil n. Statik", "t": "Stahlspundwand, Profil nach Statik, gezogen", "teile": [["006.01.003.01001", 1.0]], "std": true}, {"k": "AZ 13 verbleibt", "t": "Spundwand AZ 13, verbleibt", "teile": [["006.03.002.01001", 1.0]], "std": true}, {"k": "AZ 18 verbleibt", "t": "Spundwand AZ 18, verbleibt", "teile": [["006.03.002.02001", 1.0]], "std": true}, {"k": "AZ 26 verbleibt", "t": "Spundwand AZ 26, verbleibt", "teile": [["006.03.002.03001", 1.0]]}]}, {"name": "Rückhaltung", "optionen": [{"k": "", "t": "frei auskragend", "teile": [], "std": true}, {"k": "Gurt + Steifen", "t": "Gurtung und Aussteifung Stahl, ca. 25 kg/m²", "teile": [["006.03.005.01001", 0.025]], "std": true}, {"k": "Gurt + Anker", "t": "Gurtung 15 kg/m², Verpressanker 18 m, 1 je 12,5 m²", "teile": [["006.03.005.01001", 0.015], ["006.03.004.02001", 0.08]]}]}, {"name": "Baustelleneinrichtung", "optionen": [{"k": "BE /300 m²", "t": "BE Rammgerät anteilig bei 300 m²", "teile": [["006.01.001.02001", 0.0033]], "std": true}, {"k": "BE /150 m²", "t": "BE Rammgerät anteilig bei 150 m²", "teile": [["006.01.001.02001", 0.0067]], "std": true}]}]}', 'neubau', 8),
  ('312.03', '312', 'Bohrpfahlwand', 'm²', 'Baugrubenwand aus Bohrpfählen (aufgelöst, tangierend oder überschnitten) bis 8 m, bei Bedarf rückverankert, mit anteiliger BE des Großbohrgeräts.', 'Ansichtsfläche der Pfahlwand', '{"fest": [], "schichten": [{"name": "Pfahlwand", "optionen": [{"k": "aufgelöst Ø620", "t": "aufgelöste Bohrpfahlwand Ø 620 mm", "teile": [["006.03.008.01001", 1.0]], "std": true}, {"k": "tangierend Ø620", "t": "tangierende Bohrpfahlwand Ø 620 mm", "teile": [["006.03.008.02001", 1.0]], "std": true}, {"k": "überschn. Ø880", "t": "überschnittene, wasserdichte Bohrpfahlwand Ø 880 mm", "teile": [["006.03.008.03001", 1.0]], "std": true}]}, {"name": "Rückverankerung", "optionen": [{"k": "", "t": "ohne Anker", "teile": [], "std": true}, {"k": "Kurzzeitanker", "t": "Verpressanker Litze 18 m, 1 je 12 m²", "teile": [["006.03.004.02001", 0.083]], "std": true}, {"k": "Daueranker", "t": "Daueranker Stab 12 m, 1 je 12 m²", "teile": [["006.03.004.03001", 0.083]]}]}, {"name": "Baustelleneinrichtung", "optionen": [{"k": "BE /400 m²", "t": "BE Großbohrgerät anteilig bei 400 m²", "teile": [["006.01.001.03001", 0.0025]], "std": true}, {"k": "BE /200 m²", "t": "BE Großbohrgerät anteilig bei 200 m²", "teile": [["006.01.001.03001", 0.005]], "std": true}]}]}', 'neubau', 9),
  ('312.04', '312', 'Schlitzwand', 'm²', 'Baugrubenumschließung als Schlitzwand bis 12 m Tiefe, wasserundurchlässig, mit Rückverankerung nach Statik und anteiliger BE.', 'Ansichtsfläche der Schlitzwand', '{"fest": [], "schichten": [{"name": "Schlitzwand", "optionen": [{"k": "d = 60 cm", "t": "Schlitzwand d = 60 cm", "teile": [["006.03.009.01001", 1.0]], "std": true}, {"k": "d = 80 cm", "t": "Schlitzwand d = 80 cm", "teile": [["006.03.009.02001", 1.0]], "std": true}, {"k": "d = 100 cm", "t": "Schlitzwand d = 100 cm", "teile": [["006.03.009.03001", 1.0]], "std": true}]}, {"name": "Rückverankerung", "optionen": [{"k": "", "t": "ohne Anker (ausgesteift über Decken)", "teile": [], "std": true}, {"k": "Kurzzeitanker", "t": "Verpressanker Litze 18 m, 1 je 15 m²", "teile": [["006.03.004.02001", 0.067]], "std": true}, {"k": "Daueranker", "t": "Daueranker Stab 18 m, 1 je 15 m²", "teile": [["006.03.004.04001", 0.067]]}]}, {"name": "Baustelleneinrichtung", "optionen": [{"k": "BE /500 m²", "t": "BE Großgerät anteilig bei 500 m²", "teile": [["006.04.006.03001", 0.002]], "std": true}]}]}', 'neubau', 10),
