  ('334.14', '334', 'Kellerfenster mit Lichtschacht je St', 'St', 'Kellerfenster aus Kunststoff (Kipp) mit Anschlussabdichtung, wahlweise mit Lichtschacht und Sicherung.', 'Anzahl der Kellerfenster', '{"fest": [], "schichten": [{"name": "Kellerfenster", "optionen": [{"k": "KF 80×60", "t": "Kellerfenster Kunststoff 80 × 60 cm", "teile": [["026.01.009.01001", 1.0], ["026.05.001.01001", 2.8]], "std": true}, {"k": "KF 100×75", "t": "Kellerfenster Kunststoff 100 × 75 cm", "teile": [["026.01.009.02001", 1.0], ["026.05.001.01001", 3.5]], "std": true}]}, {"name": "Lichtschacht", "optionen": [{"k": "", "t": "ohne Lichtschacht", "teile": [], "std": true}, {"k": "LS Kunststoff", "t": "Lichtschacht Kunststoff 100 × 60 × 40 cm, Anschluss abgedichtet", "teile": [["031.03.005.01001", 1.0], ["018.03.005.01001", 1.0]], "std": true}, {"k": "LS Beton", "t": "Lichtschacht Betonfertigteil 100 × 40 cm, Anschluss abgedichtet", "teile": [["013.09.007.01001", 1.0], ["018.03.005.01001", 1.0]]}]}, {"name": "Sicherung", "optionen": [{"k": "", "t": "ohne Sicherung", "teile": [], "std": true}, {"k": "Gitter", "t": "Sicherheitsgitter Stahl verzinkt", "teile": [["031.02.008.01001", 1.0]], "std": true}, {"k": "Insektenschutz", "t": "Insektenschutz-Lichtschachtabdeckung", "teile": [["030.04.001.07001", 1.0]]}]}]}', 'neubau,altbau', 92),
  ('334.15', '334', 'Fenstertausch Bestand je St', 'St', 'Austausch eines Bestandsfensters (ca. 1,26 × 1,38 m): Altfenster ausbauen und entsorgen, neues Fenster mit RAL-Anschluss einbauen, Leibungen beiputzen, Fensterbänke erneuern.', 'Anzahl der zu tauschenden Fenster', '{"fest": [["026.05.005.02001", 1.0], ["026.05.001.01001", 5.3], ["026.05.014.01001", 1.75]], "schichten": [{"name": "Fenster neu", "optionen": [{"k": "Kunststoff", "t": "Kunststofffenster Uw 0,95", "teile": [["026.01.001.02001", 1.75]], "std": true}, {"k": "Kunststoff Uw 0,8", "t": "Kunststofffenster Uw 0,80", "teile": [["026.01.001.04001", 1.75]], "std": true}, {"k": "Holz", "t": "Holzfenster Uw 0,95", "teile": [["026.01.002.01001", 1.75]], "std": true}, {"k": "Holz-Alu", "t": "Holz-Alu-Fenster Uw 0,85", "teile": [["026.01.003.02001", 1.75]], "std": true}, {"k": "Denkmal", "t": "Kastenfenster Holz über 1,5 m²", "teile": [["026.01.014.02001", 1.75]]}]}, {"name": "Leibung", "optionen": [{"k": "beiputzen", "t": "Leibungen nach Fenstertausch beiputzen", "teile": [["026.05.006.01001", 4.0]], "std": true}, {"k": "WDVS nacharbeiten", "t": "Leibungen beiputzen, Anschluss im WDVS nacharbeiten", "teile": [["026.05.006.01001", 4.0], ["023.04.017.01001", 4.0]], "std": true}]}, {"name": "Fensterbänke", "optionen": [{"k": "FBa Alu neu", "t": "Alu-Fensterbank außen erneuern, innen bleibt", "teile": [["022.03.005.01001", 1.26]], "std": true}, {"k": "FBa + FBi neu", "t": "Alu-Fensterbank außen und Innenfensterbank Holzwerkstoff erneuern", "teile": [["022.03.005.01001", 1.26], ["027.03.001.01001", 1.26]], "std": true}, {"k": "", "t": "Fensterbänke bleiben", "teile": []}]}, {"name": "Rollladenkasten", "optionen": [{"k": "", "t": "ohne Maßnahme", "teile": [], "std": true}, {"k": "Kasten dämmen", "t": "Rollladenkasten innen dämmen und abdichten", "teile": [["030.01.010.01001", 1.0]]}]}]}', 'altbau', 93),
