  ('334.18', '334', 'Öffnungszulage Mauerwerk Neubau', 'St', 'Zulage je Öffnung in Mauerwerks-Außenwänden: Sturz bzw. Rollladenkasten als Sturz, Leibungen und Fensterbankanschluss. Fenster gesondert.', 'Anzahl der Öffnungen je Sturztyp', '{"fest": [], "schichten": [{"name": "Sturz", "optionen": [{"k": "Flachsturz 17,5", "t": "Flachsturz 1,26 m für Wand 17,5 cm", "teile": [["012.04.001.02001", 1.0]], "std": true}, {"k": "Flachsturz 24", "t": "Flachsturz 1,51 m für Wand 24 cm", "teile": [["012.04.001.03001", 1.0]], "std": true}, {"k": "Flachsturz 36,5", "t": "Flachsturz 2,01 m für Wand 36,5 cm", "teile": [["012.04.001.04001", 1.0]]}, {"k": "U-Schale 24", "t": "U-Schale 1,5 m mit Ortbeton und Bewehrung", "teile": [["012.04.003.01001", 1.5], ["013.04.006.01001", 0.03]], "std": true}, {"k": "RL-Kasten 1,26", "t": "Rollladen-/Raffstorekasten als Sturz 1,26 m", "teile": [["012.04.002.01001", 1.0]], "std": true}, {"k": "RL-Kasten 2,01", "t": "Rollladen-/Raffstorekasten als Sturz 2,01 m", "teile": [["012.04.002.02001", 1.0]]}]}, {"name": "Leibungen", "optionen": [{"k": "Leibung geputzt", "t": "Leibungen innen und außen geputzt, ca. 3,5 m", "teile": [["023.02.004.01001", 3.5], ["023.03.002.01001", 3.5]], "std": true}, {"k": "Leibung WDVS", "t": "innen geputzt, außen WDVS-Leibungsdämmung, ca. 3,5 m", "teile": [["023.02.004.01001", 3.5], ["023.04.006.01001", 3.5]], "std": true}]}, {"name": "Fensterbankanschluss", "optionen": [{"k": "", "t": "im Fensteraufbau enthalten", "teile": [], "std": true}, {"k": "FB-Anschluss WDVS", "t": "Fensterbankanschluss im WDVS mit Bordprofil", "teile": [["023.04.007.01001", 1.0]], "std": true}]}]}', 'neubau', 96),
