  ('481.01', '481', 'KNX-Raumautomation je Raum', 'St', 'Raumautomation in KNX je Raum: anteilige Aktorik für Licht, Sonnenschutz und Heizung, Bediengeräte, Busleitung, anteiliges Systemzubehör, Programmierung und Einregulierung.', 'Anzahl der Räume', '{"fest": [["070.01.001.01001", 0.1], ["070.03.004.01001", 0.05], ["070.03.008.01001", 1]], "schichten": [{"name": "Funktionen", "optionen": [{"k": "Licht + Heizung", "t": "2 Schaltkanäle, 1 Heizkanal, 4 Datenpunkte", "teile": [["070.01.002.02001", 0.25], ["070.01.005.01001", 0.1667], ["070.02.003.01001", 4]], "std": true}, {"k": "+ Jalousie", "t": "2 Schaltkanäle, 2 Jalousiekanäle, 1 Heizkanal, 7 Datenpunkte", "teile": [["070.01.002.02001", 0.25], ["070.01.003.02001", 0.25], ["070.01.005.01001", 0.1667], ["070.02.003.01001", 7]], "std": true}, {"k": "+ Dimmen", "t": "Dimmkanal, 2 Jalousiekanäle, 1 Heizkanal, 8 Datenpunkte", "teile": [["070.01.004.01001", 0.5], ["070.01.003.02001", 0.25], ["070.01.005.01001", 0.1667], ["070.02.003.01001", 8]], "std": true}, {"k": "Büro Konstantl.", "t": "Präsenzmelder Konstantlicht, DALI-Gateway anteilig, Jalousie, Heizung, 10 DP", "teile": [["070.01.007.01001", 1], ["070.03.004.02001", 0.125], ["070.01.003.02001", 0.25], ["070.01.005.01001", 0.1667], ["070.02.003.01001", 10]]}]}, {"name": "Bedienung", "optionen": [{"k": "Taster 4-f. RTR", "t": "KNX-Tastsensor 4-fach mit Raumtemperaturregler", "teile": [["070.01.006.01001", 1]], "std": true}, {"k": "Taster 8-f. RTR", "t": "KNX-Tastsensor 8-fach mit Raumtemperaturregler", "teile": [["070.01.006.02001", 1]], "std": true}, {"k": "Raumsensor CO₂", "t": "Raumsensor CO₂/Temperatur/Feuchte, Bus", "teile": [["070.03.001.01001", 1]]}]}, {"name": "Busleitung", "optionen": [{"k": "Bus 20 m", "t": "KNX-Busleitung ca. 20 m", "teile": [["070.01.009.01001", 20.0]], "std": true}, {"k": "Bus 35 m", "t": "KNX-Busleitung ca. 35 m", "teile": [["070.01.009.01001", 35.0]], "std": true}]}, {"name": "Visualisierung", "optionen": [{"k": "", "t": "ohne", "teile